script:
const a = box(30, 20, 10);
move(a, [0, -30, 0]);
hole(a, { across: 4 });
round(a.edge('top', 'front'), 2);

const a = box(30, 20, 10);
move(a, [0, 0, 10]);
hole(a, { across: 4 });
hollow(a, { wall: 2, open: 'top' });

const a = box(30, 20, 10);
const b = box(10, 10, 10, { at: [50, 0, 0] });
move(b, [0, 30, 0]);
round(a.edge('top', 'front'), 2);

const a = box(30, 20, 10);
const b = box(10, 10, 10, { at: [50, 0, 0] });
turn(b, [0, 0, 30]);
hollow(a, { wall: 2, open: 'top' });

const a = box(30, 20, 10);
round(a.edge('top', 'front'), 2);
move(a, [0, 0, 10]);
hole(a, { across: 4 });

const a = box(10, 10, 10, { at: [20, 0, 0] });
move(a, [0, 0, 5]);
const m = mirror(a, 'left-right');
round(m.edge('top', 'front'), 1);

const a = box(10, 10, 10);
move(a, [0, 0, 10]);
const p = repeat(a, { count: 2, step: [15, 0, 0] });
hollow(p, { wall: 1, open: 'top' });
